from calculator_app.ui import CalculatorUI
from calculator_app.operations import add, subtract, multiply, divide


class CalculatorBackend:
    def __init__(self):
        self.ui = CalculatorUI()
        self.ui.set_calculate_callback(self.calculate)

    def calculate(self, operation, num1, num2):
        try:
            num1 = float(num1)
            num2 = float(num2)
        except ValueError:
            self.ui.display_result("Error: Invalid input")
            return

        if operation == "add":
            result = add(num1, num2)
        elif operation == "subtract":
            result = subtract(num1, num2)
        elif operation == "multiply":
            result = multiply(num1, num2)
        elif operation == "divide":
            if num2 == 0:
                self.ui.display_result("Error: Division by zero")
                return
            result = divide(num1, num2)
        else:
            self.ui.display_result("Error: Unknown operation")
            return

        self.ui.display_result(result)

    def run(self):
        self.ui.run()


if __name__ == "__main__":
    backend = CalculatorBackend()
    backend.run()

import unittest
from calculator_app.backend import Calculator

class TestCalculatorOperations(unittest.TestCase):

    def setUp(self):
        self.calculator = Calculator()

    def test_addition(self):
        result = self.calculator.add(5, 3)
        self.assertEqual(result, 8, "Addition test failed!")

    def test_subtraction(self):
        result = self.calculator.subtract(10, 4)
        self.assertEqual(result, 6, "Subtraction test failed!")

    def test_multiplication(self):
        result = self.calculator.multiply(7, 3)
        self.assertEqual(result, 21, "Multiplication test failed!")

    def test_division(self):
        result = self.calculator.divide(12, 4)
        self.assertEqual(result, 3, "Division test failed!")

    def test_division_by_zero(self):
        with self.assertRaises(ZeroDivisionError):
            self.calculator.divide(5, 0)

